//! Pluralization / singularization rules.
//!
//! Behavior reverse-engineered from the reference C++ `inflection` library.
//! All operations are byte-oriented (the C++ original works on `std::string`
//! with C-locale semantics, i.e. ASCII-only case handling).

/// Words that are both singular and plural. The check is an exact,
/// case-sensitive, whole-word match.
pub const UNCOUNTABLES: &[&[u8]] = &[
    b"equipment",
    b"information",
    b"rice",
    b"money",
    b"species",
    b"series",
    b"fish",
    b"sheep",
    b"jeans",
    b"police",
];

fn is_uncountable(word: &[u8]) -> bool {
    UNCOUNTABLES.iter().any(|u| *u == word)
}

/// pluralize: uncountables stay unchanged, everything else just gets an
/// "s" appended (none of the fancier rules of the original library ever
/// fire because a catch-all rule shadows them).
pub fn pluralize(word: &[u8]) -> Vec<u8> {
    if is_uncountable(word) {
        return word.to_vec();
    }
    let mut out = word.to_vec();
    out.push(b's');
    out
}

fn ends_with(word: &[u8], suffix: &[u8]) -> bool {
    word.len() >= suffix.len() && &word[word.len() - suffix.len()..] == suffix
}

/// singularize: uncountables stay unchanged; otherwise the first matching
/// rule wins. The C++ library stores its rules in a `std::map` keyed by the
/// pattern string, so rules are applied in lexicographic order of the
/// pattern. Finally a trailing 's' is stripped.
pub fn singularize(word: &[u8]) -> Vec<u8> {
    if is_uncountable(word) {
        return word.to_vec();
    }
    let n = word.len();

    // ((a)naly|(b)a|(d)iagno|(p)arenthe|(p)rogno|(s)ynop|(t)he)ses$ -> $1$2sis
    // ($2 only participates for the "(a)naly" branch.)
    const SIS_RULES: &[(&[u8], &[u8])] = &[
        (b"analyses", b"analyasis"),
        (b"bases", b"basis"),
        (b"diagnoses", b"diagnosis"),
        (b"parentheses", b"parenthesis"),
        (b"prognoses", b"prognosis"),
        (b"synopses", b"synopsis"),
        (b"theses", b"thesis"),
    ];
    for (suffix, repl) in SIS_RULES {
        if ends_with(word, suffix) {
            let mut out = word[..n - suffix.len()].to_vec();
            out.extend_from_slice(repl);
            return out;
        }
    }

    // ([^aeiouy]|qu)ies$ -> $1y
    if n >= 4 && ends_with(word, b"ies") {
        let c = word[n - 4];
        let consonant = !matches!(c, b'a' | b'e' | b'i' | b'o' | b'u' | b'y');
        let qu = n >= 5 && word[n - 5] == b'q' && c == b'u';
        if consonant || qu {
            let mut out = word[..n - 3].to_vec();
            out.push(b'y');
            return out;
        }
    }

    // ([^f])ves$ -> $1fe
    if n >= 4 && ends_with(word, b"ves") && word[n - 4] != b'f' {
        let mut out = word[..n - 3].to_vec();
        out.extend_from_slice(b"fe");
        return out;
    }

    // ([lr])ves$ -> $1f
    if n >= 4 && ends_with(word, b"ves") && matches!(word[n - 4], b'l' | b'r') {
        let mut out = word[..n - 3].to_vec();
        out.push(b'f');
        return out;
    }

    // ([m|l])ice$ -> $1ouse  (character class is literally m, | or l)
    if n >= 4 && ends_with(word, b"ice") && matches!(word[n - 4], b'm' | b'|' | b'l') {
        let mut out = word[..n - 3].to_vec();
        out.extend_from_slice(b"ouse");
        return out;
    }

    // ([ti])a$ -> $1um
    if n >= 2 && word[n - 1] == b'a' && matches!(word[n - 2], b't' | b'i') {
        let mut out = word[..n - 1].to_vec();
        out.extend_from_slice(b"um");
        return out;
    }

    // (^analy)ses$ -> $1sis
    if word == b"analyses" {
        return b"analysis".to_vec();
    }

    // (alias|status)es$ -> $1
    if ends_with(word, b"aliases") || ends_with(word, b"statuses") {
        return word[..n - 2].to_vec();
    }

    // (bus)es$ -> $1
    if ends_with(word, b"buses") {
        return word[..n - 2].to_vec();
    }

    // (cris|ax|test)es$ -> $1is
    if ends_with(word, b"crises") || ends_with(word, b"axes") || ends_with(word, b"testes") {
        let mut out = word[..n - 2].to_vec();
        out.extend_from_slice(b"is");
        return out;
    }

    // (hive)s$ -> $1
    if ends_with(word, b"hives") {
        return word[..n - 1].to_vec();
    }

    // (m)ovies$ -> $1ovie
    if ends_with(word, b"movies") {
        return word[..n - 1].to_vec();
    }

    // (matr)ices$ -> $1ix
    if ends_with(word, b"matrices") {
        let mut out = word[..n - 4].to_vec();
        out.extend_from_slice(b"ix");
        return out;
    }

    // (n)ews$ -> $1ews  (identity, but prevents the trailing-s strip)
    if ends_with(word, b"news") {
        return word.to_vec();
    }

    // (o)es$ -> $1
    if ends_with(word, b"oes") {
        return word[..n - 2].to_vec();
    }

    // (octop|vir)i$ -> $1us
    if ends_with(word, b"octopi") || ends_with(word, b"viri") {
        let mut out = word[..n - 1].to_vec();
        out.extend_from_slice(b"us");
        return out;
    }

    // (quiz)zes$ -> $1
    if ends_with(word, b"quizzes") {
        return word[..n - 3].to_vec();
    }

    // (s)eries$ -> $1eries  (identity, but prevents the trailing-s strip)
    if ends_with(word, b"series") {
        return word.to_vec();
    }

    // (shoe)s$ -> $1
    if ends_with(word, b"shoes") {
        return word[..n - 1].to_vec();
    }

    // (tive)s$ -> $1
    if ends_with(word, b"tives") {
        return word[..n - 1].to_vec();
    }

    // (vert|ind)ices$ -> $1ex
    if ends_with(word, b"vertices") || ends_with(word, b"indices") {
        let mut out = word[..n - 4].to_vec();
        out.extend_from_slice(b"ex");
        return out;
    }

    // (x|ch|ss|sh)es$ -> $1
    if ends_with(word, b"xes")
        || ends_with(word, b"ches")
        || ends_with(word, b"sses")
        || ends_with(word, b"shes")
    {
        return word[..n - 2].to_vec();
    }

    // ^(ox)en$ -> $1
    if word == b"oxen" {
        return b"ox".to_vec();
    }

    // s$ -> ""
    if n >= 1 && word[n - 1] == b's' {
        return word[..n - 1].to_vec();
    }

    word.to_vec()
}

/// isPlural: true when singularize changes the word.
pub fn is_plural(word: &[u8]) -> bool {
    singularize(word) != word
}

/// isSingular: true when singularize leaves the word unchanged.
pub fn is_singular(word: &[u8]) -> bool {
    singularize(word) == word
}

/// ordinalize: 1 -> "1st", 2 -> "2nd", 3 -> "3rd", everything else -> "Nth"
/// (except 11-13 which take "th"). Never exercised by test20 itself.
pub fn ordinalize(number: i64) -> String {
    let abs = number.unsigned_abs();
    let suffix = match abs % 100 {
        11..=13 => "th",
        _ => match abs % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        },
    };
    format!("{}{}", number, suffix)
}

