    if ends_with(word, b"octopi") || ends_with(word, b"viri") {
        let mut out = word[..n - 1].to_vec();
        out.extend_from_slice(b"us");
        return out;
    }

    // (quiz)zes$ -> $1
    if ends_with(word, b"quizzes") {
        return word[..n - 3].to_vec();
    }

    // (s)eries$ -> $1eries  (identity, but prevents the trailing-s strip)
    if ends_with(word, b"series") {
        return word.to_vec();
    }

    // (shoe)s$ -> $1
    if ends_with(word, b"shoes") {
        return word[..n - 1].to_vec();
    }

    // (tive)s$ -> $1
    if ends_with(word, b"tives") {
        return word[..n - 1].to_vec();
    }

    // (vert|ind)ices$ -> $1ex
    if ends_with(word, b"vertices") || ends_with(word, b"indices") {
        let mut out = word[..n - 4].to_vec();
        out.extend_from_slice(b"ex");
        return out;
    }

    // (x|ch|ss|sh)es$ -> $1
    if ends_with(word, b"xes")
        || ends_with(word, b"ches")
        || ends_with(word, b"sses")
        || ends_with(word, b"shes")
    {
        return word[..n - 2].to_vec();
    }

    // ^(ox)en$ -> $1
    if word == b"oxen" {
        return b"ox".to_vec();
    }

    // s$ -> ""
    if n >= 1 && word[n - 1] == b's' {
        return word[..n - 1].to_vec();
    }

    word.to_vec()
}

/// isPlural: true when singularize changes the word.
pub fn is_plural(word: &[u8]) -> bool {
    singularize(word) != word
}

/// isSingular: true when singularize leaves the word unchanged.
pub fn is_singular(word: &[u8]) -> bool {
    singularize(word) == word
}

/// ordinalize: 1 -> "1st", 2 -> "2nd", 3 -> "3rd", everything else -> "Nth"
/// (except 11-13 which take "th"). Never exercised by test20 itself.
pub fn ordinalize(number: i64) -> String {
    let abs = number.unsigned_abs();
    let suffix = match abs % 100 {
        11..=13 => "th",
        _ => match abs % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        },
    };
    format!("{}{}", number, suffix)
}

