//! String case and formatting transformations.
//!
//! Byte-oriented, ASCII-only semantics (matching C-locale `std::string`
//! behavior of the original C++ library).

fn to_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - 32
    } else {
        b
    }
}

fn to_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b + 32
    } else {
        b
    }
}

/// upcase: ASCII uppercase of every byte.
pub fn upcase(word: &[u8]) -> Vec<u8> {
    word.iter().map(|&b| to_upper(b)).collect()
}

/// downcase: ASCII lowercase of every byte.
pub fn downcase(word: &[u8]) -> Vec<u8> {
    word.iter().map(|&b| to_lower(b)).collect()
}

/// capitalize: first byte uppercased, all remaining bytes lowercased.
pub fn capitalize(word: &[u8]) -> Vec<u8> {
    let mut out = downcase(word);
    if let Some(first) = out.first_mut() {
        *first = to_upper(*first);
    }
    out
}

/// decapitalize: first byte lowercased, rest unchanged.
pub fn decapitalize(word: &[u8]) -> Vec<u8> {
    let mut out = word.to_vec();
    if let Some(first) = out.first_mut() {
        *first = to_lower(*first);
    }
    out
}

/// camelize: split on '_'; uppercase the first byte of each piece (the first
/// piece only when `upper_first` is set). Everything else is left as-is.
pub fn camelize(word: &[u8], upper_first: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for (i, piece) in word.split(|&b| b == b'_').enumerate() {
        if i == 0 && !upper_first {
            out.extend_from_slice(piece);
        } else {
            for (j, &b) in piece.iter().enumerate() {
                out.push(if j == 0 { to_upper(b) } else { b });
            }
        }
    }
    out
}

/// underscore: every ASCII uppercase byte (except at index 0) is prefixed
/// with '_' and lowercased. Other bytes pass through unchanged.
pub fn underscore(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len() + 4);
    for (i, &b) in word.iter().enumerate() {
        if b.is_ascii_uppercase() {
            if i > 0 {
                out.push(b'_');
            }
            out.push(to_lower(b));
        } else {
            out.push(b);
        }
    }
    out
}

/// humanize: '_' becomes a space, then the first byte is uppercased.
pub fn humanize(word: &[u8]) -> Vec<u8> {
    let mut out: Vec<u8> = word
        .iter()
        .map(|&b| if b == b'_' { b' ' } else { b })
        .collect();
    if let Some(first) = out.first_mut() {
        *first = to_upper(*first);
    }
    out
}

/// titleize: the byte at the start or right after a space is uppercased,
/// every other byte is lowercased.
pub fn titleize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for (i, &b) in word.iter().enumerate() {
        if i == 0 || word[i - 1] == b' ' {
            out.push(to_upper(b));
        } else {
            out.push(to_lower(b));
        }
    }
    out
}

/// dasherize: '_' becomes '-'.
pub fn dasherize(word: &[u8]) -> Vec<u8> {
    word.iter()
        .map(|&b| if b == b'_' { b'-' } else { b })
        .collect()
}

/// parameterize: keep ASCII alphanumerics (lowercased), turn spaces into
/// '-', drop every other byte.
pub fn parameterize(word: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for &b in word {
        if b.is_ascii_alphanumeric() {
            out.push(to_lower(b));
        } else if b == b' ' {
            out.push(b'-');
        }
    }
    out
}

/// truncate: if the byte length exceeds `length`, keep the first
/// `length - 3` bytes and append "...". Otherwise return unchanged.
pub fn truncate(word: &[u8], length: usize) -> Vec<u8> {
    if word.len() > length {
        let mut out = word[..length - 3].to_vec();
        out.extend_from_slice(b"...");
        out
    } else {
        word.to_vec()
    }
}

/// demodulize: substring after the last ':' plus one extra byte
/// (the original does `word.substr(word.rfind(':') + 2)`).
/// Reproduces the C++ `std::out_of_range` abort when `pos + 2` exceeds
/// the string length (e.g. empty input or input ending with ':').
pub fn demodulize(word: &[u8]) -> Vec<u8> {
    let pos = match word.iter().rposition(|&b| b == b':') {
        // rfind(':') + 2; with no ':' C++ computes npos + 2 which wraps to 1.
        Some(i) => i + 2,
        None => 1,
    };
    if pos > word.len() {
        eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
        eprintln!(
            "  what():  basic_string::substr: __pos (which is {}) > this->size() (which is {})",
            pos,
            word.len()
        );
        std::process::abort();
    }
    word[pos..].to_vec()
}

