//! Rust port of tests/test20.cpp — exercises 20 inflection API calls.
//!
//! Byte-for-byte compatible with the C++ reference binary, including its
//! abort behavior on inputs where demodulize() would throw std::out_of_range.

mod inflection;

use std::io::Write;
use std::os::unix::ffi::OsStrExt;

fn main() {
    let args: Vec<Vec<u8>> = std::env::args_os()
        .map(|a| a.as_bytes().to_vec())
        .collect();

    let mut all_results: Vec<Vec<u8>> = Vec::new();

    if args.len() > 1 {
        let base_word: &[u8] = &args[1];

        // 1-5: basic transformations
        all_results.push(inflection::pluralize(base_word));
        all_results.push(inflection::singularize(base_word));
        all_results.push(inflection::camelize(base_word, false));
        all_results.push(inflection::camelize(base_word, true));
        all_results.push(inflection::underscore(base_word));

        // 6-10: more transformations
        all_results.push(inflection::classify(base_word));
        all_results.push(inflection::tableize(base_word));
        all_results.push(inflection::humanize(base_word));
        all_results.push(inflection::titleize(base_word));
        all_results.push(inflection::dasherize(base_word));

        // 11-15: parameterize and others
        all_results.push(inflection::parameterize(base_word));
        let mut wrapped: Vec<u8> = b"A ".to_vec();
        wrapped.extend_from_slice(base_word);
        wrapped.extend_from_slice(b" Test");
        all_results.push(inflection::parameterize(&wrapped));
        all_results.push(inflection::upcase(base_word));
        all_results.push(inflection::downcase(base_word));
        all_results.push(inflection::capitalize(base_word));

        // 16-20: extra features
        all_results.push(inflection::decapitalize(base_word));
        all_results.push(inflection::truncate(base_word, 5));
        let mut qualified: Vec<u8> = b"Test::".to_vec();
        qualified.extend_from_slice(base_word);
        all_results.push(inflection::demodulize(&qualified));
        all_results.push(
            if inflection::is_plural(base_word) { b"1".to_vec() } else { b"0".to_vec() },
        );
        all_results.push(
            if inflection::is_singular(base_word) { b"1".to_vec() } else { b"0".to_vec() },
        );
    }

    // If not enough results, use ordinals as defaults.
    if all_results.len() < 20 && args.len() > 1 {
        let mut i = 1;
        while i <= 5 && all_results.len() < 20 {
            all_results.push(inflection::ordinalize(i).into_bytes());
            i += 1;
        }
    }

    // Print exactly 20 results.
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for r in all_results.iter().take(20) {
        out.write_all(r).unwrap();
        out.write_all(b"\n").unwrap();
    }
}

